#include "client/graphics/eqe1_loader.h"
#include "client/graphics/eqe1_format.h"

#include <cassert>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

using namespace EQT::Graphics;

// Path to a known good .eqe1 file (generated by E02)
static const char* TEST_CHR_FILE = "/mnt/projects/EverQuest_ETC1/qeynos2_chr.eqe1";
static const char* TEST_OBJ_FILE = "/mnt/projects/EverQuest_ETC1/qeynos2_obj.eqe1";

static int testsPassed = 0;
static int testsFailed = 0;

#define TEST(name) \
    printf("  %s... ", #name); fflush(stdout)

#define PASS() \
    do { printf("PASS\n"); testsPassed++; } while(0)

#define FAIL(msg) \
    do { printf("FAIL: %s\n", msg); testsFailed++; } while(0)

#define ASSERT_TRUE(expr, msg) \
    do { if (!(expr)) { FAIL(msg); return; } } while(0)

void testOpenValidFile() {
    TEST(OpenValidFile);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");
    ASSERT_TRUE(loader.isOpen(), "not open after open()");
    ASSERT_TRUE(loader.getEntryCount() > 0, "zero entries");
    PASS();
}

void testLookupExistingTexture() {
    TEST(LookupExistingTexture);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");

    // "batch0001" is the first texture in qeynos2_chr (known from E02 verbose output)
    auto* entry = loader.lookup("batch0001");
    ASSERT_TRUE(entry != nullptr, "lookup returned nullptr");
    ASSERT_TRUE(entry->width > 0, "width is 0");
    ASSERT_TRUE(entry->height > 0, "height is 0");
    ASSERT_TRUE(entry->mipLevels > 0, "mipLevels is 0");
    ASSERT_TRUE(entry->data != nullptr, "data is nullptr");
    ASSERT_TRUE(entry->mipLevels == computeMipLevels(entry->width, entry->height),
                "mipLevels mismatch");

    uint32_t expectedSize = etc1MipChainSize(entry->width, entry->height, entry->mipLevels);
    ASSERT_TRUE(entry->dataSize == expectedSize, "dataSize mismatch");
    PASS();
}

void testLookupNonexistent() {
    TEST(LookupNonexistent);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");

    auto* entry = loader.lookup("this_texture_does_not_exist");
    ASSERT_TRUE(entry == nullptr, "expected nullptr for nonexistent texture");
    PASS();
}

void testAlphaCompanion() {
    TEST(AlphaCompanion);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_OBJ_FILE), "open() failed");

    // "fire1" is known to have alpha (from E02 verbose output)
    auto* entry = loader.lookup("fire1");
    ASSERT_TRUE(entry != nullptr, "lookup returned nullptr for fire1");
    ASSERT_TRUE(entry->hasAlpha, "fire1 should have alpha");
    ASSERT_TRUE(entry->alphaData != nullptr, "alphaData is nullptr");
    ASSERT_TRUE(entry->alphaDataSize > 0, "alphaDataSize is 0");

    // Alpha companion should also exist as separate entry
    auto* alphaEntry = loader.lookup("fire1_alpha");
    ASSERT_TRUE(alphaEntry != nullptr, "fire1_alpha companion not found");
    ASSERT_TRUE(alphaEntry->width == entry->width, "alpha width mismatch");
    ASSERT_TRUE(alphaEntry->height == entry->height, "alpha height mismatch");
    PASS();
}

void testRawDataEntry() {
    TEST(RawDataEntry);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");

    auto rawNames = loader.getRawDataNames();
    ASSERT_TRUE(!rawNames.empty(), "no raw data entries");

    // Should have at least one .wld file
    bool foundWld = false;
    for (const auto& name : rawNames) {
        if (name.find(".wld") != std::string::npos) {
            foundWld = true;
            break;
        }
    }
    ASSERT_TRUE(foundWld, "no .wld in raw data entries");

    // Retrieve it
    const uint8_t* data = nullptr;
    uint32_t size = 0;
    ASSERT_TRUE(loader.getRawData(rawNames[0], data, size), "getRawData failed");
    ASSERT_TRUE(data != nullptr, "raw data pointer is null");
    ASSERT_TRUE(size > 0, "raw data size is 0");
    PASS();
}

void testInvalidFile() {
    TEST(InvalidFile);
    EQE1Loader loader;

    // Nonexistent
    ASSERT_TRUE(!loader.open("/nonexistent/path.eqe1"), "should fail on nonexistent");

    // Wrong magic — create a temp file with bad header
    {
        const char* tmpPath = "/tmp/test_bad_magic.eqe1";
        std::ofstream out(tmpPath, std::ios::binary);
        uint32_t badMagic = 0xDEADBEEF;
        out.write(reinterpret_cast<const char*>(&badMagic), 4);
        char zeros[12] = {};
        out.write(zeros, 12);
        out.close();
        ASSERT_TRUE(!loader.open(tmpPath), "should fail on bad magic");
    }

    // Truncated — just 4 bytes
    {
        const char* tmpPath = "/tmp/test_truncated.eqe1";
        std::ofstream out(tmpPath, std::ios::binary);
        out.write("EQE1", 4);
        out.close();
        ASSERT_TRUE(!loader.open(tmpPath), "should fail on truncated file");
    }

    PASS();
}

void testMoveSemantics() {
    TEST(MoveSemantics);
    EQE1Loader loader1;
    ASSERT_TRUE(loader1.open(TEST_CHR_FILE), "open() failed");
    uint16_t count = loader1.getEntryCount();
    ASSERT_TRUE(count > 0, "zero entries");

    // Move construct
    EQE1Loader loader2(std::move(loader1));
    ASSERT_TRUE(!loader1.isOpen(), "source should be closed after move");
    ASSERT_TRUE(loader2.isOpen(), "target should be open after move");
    ASSERT_TRUE(loader2.getEntryCount() == count, "entry count mismatch after move");

    // Lookup should still work on moved-to loader
    auto* entry = loader2.lookup("batch0001");
    ASSERT_TRUE(entry != nullptr, "lookup failed after move");

    // Move assign
    EQE1Loader loader3;
    loader3 = std::move(loader2);
    ASSERT_TRUE(!loader2.isOpen(), "source should be closed after move assign");
    ASSERT_TRUE(loader3.isOpen(), "target should be open after move assign");
    ASSERT_TRUE(loader3.getEntryCount() == count, "entry count mismatch after move assign");
    PASS();
}

void testGetTextureNames() {
    TEST(GetTextureNames);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");

    auto names = loader.getTextureNames();
    ASSERT_TRUE(!names.empty(), "no texture names");

    // Should be sorted
    for (size_t i = 1; i < names.size(); ++i) {
        ASSERT_TRUE(names[i] >= names[i-1], "texture names not sorted");
    }
    PASS();
}

// P03: v2 pack round-trip -- build a minimal synthetic v2 file in /tmp with
// one RGB565 entry, one RGBA4444 entry (hasAlpha=1, NO companion), and one
// v1-style ETC1 entry, then verify the loader dispatches payloadFormat
// correctly and accepts the version-2 header.
void testV2PayloadFormats() {
    TEST(V2PayloadFormats);
    const char* tmpPath = "/tmp/test_v2_pack.eqe1";

    auto makeEntry = [](const char* name, uint16_t w, uint16_t h,
                        uint8_t mips, uint8_t hasAlpha, uint8_t entryType,
                        uint8_t payloadFormat, uint32_t offset, uint32_t size) {
        EQE1IndexEntry e = {};
        std::strncpy(e.name, name, EQE1_NAME_SIZE - 1);
        e.width = w; e.height = h; e.mipLevels = mips;
        e.hasAlpha = hasAlpha; e.entryType = entryType;
        e.payloadFormat = payloadFormat;
        e.dataOffset = offset; e.dataSize = size;
        return e;
    };

    // 4x4, 3 mips (4->2->1): 565 = (16+4+1)*2 = 42 bytes; etc1 = 3 blocks = 24 bytes
    uint32_t sz565 = payloadMipChainSize(4, 4, 3, EQE1_PAYLOAD_RGB565);
    uint32_t sz4444 = payloadMipChainSize(4, 4, 3, EQE1_PAYLOAD_RGBA4444);
    uint32_t szEtc1 = etc1MipChainSize(4, 4, 3);
    ASSERT_TRUE(sz565 == 42, "expected 42-byte 565 mip chain for 4x4x3");
    ASSERT_TRUE(sz4444 == 42, "expected 42-byte 4444 mip chain for 4x4x3");

    uint32_t indexEnd = sizeof(EQE1Header) + 3 * EQE1_INDEX_ENTRY_SIZE;
    uint32_t off1 = alignTo16(indexEnd);
    uint32_t off2 = alignTo16(off1 + sz565);
    uint32_t off3 = alignTo16(off2 + sz4444);

    {
        std::ofstream out(tmpPath, std::ios::binary);
        EQE1Header hdr = {};
        hdr.magic = EQE1_MAGIC;
        hdr.version = EQE1_VERSION_V2;
        hdr.numEntries = 3;
        out.write(reinterpret_cast<const char*>(&hdr), sizeof(hdr));
        auto e1 = makeEntry("opaque565", 4, 4, 3, 0, EQE1_TYPE_ETC1_RGB,
                            EQE1_PAYLOAD_RGB565, off1, sz565);
        auto e2 = makeEntry("masked4444", 4, 4, 3, 1, EQE1_TYPE_ETC1_RGB,
                            EQE1_PAYLOAD_RGBA4444, off2, sz4444);
        auto e3 = makeEntry("legacyetc1", 4, 4, 3, 0, EQE1_TYPE_ETC1_RGB,
                            EQE1_PAYLOAD_ETC1, off3, szEtc1);
        out.write(reinterpret_cast<const char*>(&e1), sizeof(e1));
        out.write(reinterpret_cast<const char*>(&e2), sizeof(e2));
        out.write(reinterpret_cast<const char*>(&e3), sizeof(e3));
        std::vector<char> payload(off3 + szEtc1 - indexEnd, 0x5A);
        out.write(payload.data(), payload.size());
    }

    EQE1Loader loader;
    ASSERT_TRUE(loader.open(tmpPath), "open() failed on v2 pack");
    ASSERT_TRUE(loader.getEntryCount() == 3, "entry count != 3");

    auto* t565 = loader.lookup("opaque565");
    ASSERT_TRUE(t565 != nullptr, "opaque565 not found");
    ASSERT_TRUE(t565->payloadFormat == EQE1_PAYLOAD_RGB565, "payloadFormat != RGB565");
    ASSERT_TRUE(!t565->hasAlpha, "opaque565 should not have alpha");
    ASSERT_TRUE(t565->dataSize == sz565, "565 dataSize mismatch");

    auto* t4444 = loader.lookup("masked4444");
    ASSERT_TRUE(t4444 != nullptr, "masked4444 not found");
    ASSERT_TRUE(t4444->payloadFormat == EQE1_PAYLOAD_RGBA4444, "payloadFormat != RGBA4444");
    ASSERT_TRUE(t4444->hasAlpha, "masked4444 should have alpha");
    // v2 alpha is in-band: NO companion entry, alphaData must stay null
    ASSERT_TRUE(t4444->alphaData == nullptr, "v2 entry must not link a companion");
    ASSERT_TRUE(loader.lookup("masked4444_alpha") == nullptr, "no _alpha entry expected");

    auto* tEtc1 = loader.lookup("legacyetc1");
    ASSERT_TRUE(tEtc1 != nullptr, "legacyetc1 not found");
    ASSERT_TRUE(tEtc1->payloadFormat == EQE1_PAYLOAD_ETC1, "payloadFormat != ETC1");
    PASS();
}

// P03: v1 packs must still load with payloadFormat decoding as ETC1 (the
// former padding byte is 0 in every v1 file).
void testV1PayloadFormatDefaultsToETC1() {
    TEST(V1PayloadFormatDefaultsToETC1);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");
    auto* entry = loader.lookup("batch0001");
    ASSERT_TRUE(entry != nullptr, "lookup returned nullptr");
    ASSERT_TRUE(entry->payloadFormat == EQE1_PAYLOAD_ETC1,
                "v1 entry payloadFormat should decode as ETC1 (0)");
    PASS();
}

void testClose() {
    TEST(Close);
    EQE1Loader loader;
    ASSERT_TRUE(loader.open(TEST_CHR_FILE), "open() failed");
    ASSERT_TRUE(loader.isOpen(), "not open");

    loader.close();
    ASSERT_TRUE(!loader.isOpen(), "still open after close");
    ASSERT_TRUE(loader.getEntryCount() == 0, "nonzero entries after close");
    ASSERT_TRUE(loader.lookup("batch0001") == nullptr, "lookup succeeded after close");
    PASS();
}

int main() {
    printf("test_eqe1_loader:\n");

    testOpenValidFile();
    testLookupExistingTexture();
    testLookupNonexistent();
    testAlphaCompanion();
    testRawDataEntry();
    testInvalidFile();
    testMoveSemantics();
    testGetTextureNames();
    testV2PayloadFormats();
    testV1PayloadFormatDefaultsToETC1();
    testClose();

    printf("\n%d passed, %d failed\n", testsPassed, testsFailed);
    return testsFailed > 0 ? 1 : 0;
}
